"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["432662"],{656790(e){e.exports=JSON.parse('{"tag":{"label":"quickstart","permalink":"/sdk/4.10.1/tags/quickstart","allTagsPath":"/sdk/4.10.1/tags","count":6,"items":[{"id":"guides/developing-apps-guide","title":"Developing ServiceNow Apps with the Now SDK","description":"Guide for ServiceNow app development using the Now SDK: project setup, fluent authoring, build/deploy workflow, and CLI reference. Start here when working on a new ServiceNow application or with the Now SDK before consulting artifact-specific guides.","permalink":"/sdk/4.10.1/guides/developing-apps-guide"},{"id":"guides/module-guide","title":"JavaScript Modules","description":"JavaScript modules are the modern, preferred approach for all server-side code in Fluent projects. Modules support import/export, provide access to typed Glide APIs via @servicenow/glide, enable code reuse across your application, and integrate with third-party npm libraries.","permalink":"/sdk/4.10.1/guides/module-guide"},{"id":"config/now-config-reference","title":"now.config.json","description":"The now.config.json file is the project configuration for a Fluent SDK application. It lives at the project root and defines the application scope, build settings, source directories, dependencies, and runtime policies. Every Fluent project requires this file.","permalink":"/sdk/4.10.1/config/now-config-reference"},{"id":"fluent/now-id-guide","title":"Now.ID","description":"Now.ID[\'key-name\'] gives a Fluent record a stable, human-readable identity. Use it to assign the $id property on any API that accepts one \u2014 the build system maps the key to a real sys_id and keeps it stable across builds.","permalink":"/sdk/4.10.1/fluent/now-id-guide"},{"id":"guides/fluent-overview","title":"ServiceNow Fluent Overview","description":"ServiceNow Fluent is a domain-specific language (DSL) based on TypeScript for defining the metadata files [sys_metadata] that make up applications. It includes APIs for tables, roles, ACLs, business rules, Automated Test Framework tests, and more.","permalink":"/sdk/4.10.1/guides/fluent-overview"},{"id":"config/keys-file","title":"The keys.ts File","description":"Every Fluent project has an auto-generated keys.ts file that maps human-readable identifiers to ServiceNow sys_ids. It\'s the registry that makes Now.ID[\'my-record\'] work.","permalink":"/sdk/4.10.1/config/keys-file"}],"unlisted":false}}')}}]);